// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import {
    AccessControlDefaultAdminRules
} from "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import {IExternalRequestsManager} from "./interfaces/IExternalRequestsManager.sol";
import {IPermissionedToken} from "./interfaces/IPermissionedToken.sol";
import {IAddressesWhitelist} from "./interfaces/IAddressesWhitelist.sol";
import {IMintGuard} from "./interfaces/IMintGuard.sol";
import {IOracle} from "./interfaces/IOracle.sol";

contract ExternalRequestsManager is IExternalRequestsManager, AccessControlDefaultAdminRules, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant UNPAUSER_ROLE = keccak256("UNPAUSER_ROLE");
    bytes32 public constant MINT_COMPLETER_ROLE = keccak256("MINT_COMPLETER_ROLE");
    bytes32 public constant BURN_COMPLETER_ROLE = keccak256("BURN_COMPLETER_ROLE");
    bytes32 public constant TREASURY_CONFIG_ROLE = keccak256("TREASURY_CONFIG_ROLE");
    bytes32 public constant ORACLE_CONFIG_ROLE = keccak256("ORACLE_CONFIG_ROLE");
    bytes32 public constant WHITELIST_CONFIG_ROLE = keccak256("WHITELIST_CONFIG_ROLE");
    bytes32 public constant ISSUANCE_CONFIG_ROLE = keccak256("ISSUANCE_CONFIG_ROLE");

    uint256 private constant _BPS_DENOMINATOR = 10_000;

    address public immutable issueToken;
    address public immutable depositToken;
    uint256 private immutable _shareScale;
    bool private immutable _shareScaleMultiplies;

    address public treasury;
    IAddressesWhitelist public providersWhitelist;
    IOracle public oracle;

    uint256 public mintRequestsCounter;
    mapping(uint256 id => Request) public mintRequests;

    uint256 public burnRequestsCounter;
    mapping(uint256 id => Request) public burnRequests;

    uint256 public minMintRequestAmount;
    uint256 public minBurnRequestAmount;
    uint256 public priceDeviationBps;

    modifier onlyAllowedProvider() {
        require(providersWhitelist.isAllowedAccount(msg.sender), UnknownProvider(msg.sender));
        _;
    }

    modifier mintRequestExist(uint256 _id) {
        require(mintRequests[_id].state != State.NULL, RequestNotExist(_id));
        _;
    }

    modifier burnRequestExist(uint256 _id) {
        require(burnRequests[_id].state != State.NULL, RequestNotExist(_id));
        _;
    }

    constructor(IExternalRequestsManager.InitParams memory p) AccessControlDefaultAdminRules(1 days, p.admin) {
        _setOracle(p.oracle);

        address base = oracle.baseAsset();
        require(base != address(0), ZeroAddress());
        require(base.code.length != 0, NotAContract(base));
        issueToken = base;

        address quote = oracle.quoteAsset();
        require(quote != address(0), ZeroAddress());
        require(quote.code.length != 0, NotAContract(quote));
        depositToken = quote;

        uint8 issueDecimals = IERC20Metadata(issueToken).decimals();
        uint8 depositDecimals = IERC20Metadata(depositToken).decimals();
        uint8 priceDecimals = oracle.priceDecimals();
        uint256 sumIssuePrice = uint256(issueDecimals) + uint256(priceDecimals);
        bool multiplies = sumIssuePrice >= depositDecimals;
        _shareScaleMultiplies = multiplies;
        _shareScale = multiplies ? 10 ** (sumIssuePrice - depositDecimals) : 10 ** (depositDecimals - sumIssuePrice);

        _setTreasury(p.treasury);
        _setProvidersWhitelist(p.providersWhitelist);
        _setPriceDeviationBps(p.priceDeviationBps);

        _assertMintGuardOracleConsistent();
    }

    function requestMint(uint256 _depositAmount, uint256 _minMintAmount)
        external
        onlyAllowedProvider
        whenNotPaused
        returns (uint256 id)
    {
        require(_depositAmount != 0, ZeroAmount());
        uint256 floor = minMintRequestAmount;
        require(_depositAmount >= floor, BelowMinRequest(_depositAmount, floor));

        IERC20(depositToken).safeTransferFrom(msg.sender, address(this), _depositAmount);

        id = mintRequestsCounter;
        mintRequests[id] = Request({
            id: id,
            provider: msg.sender,
            state: State.CREATED,
            amount: _depositAmount,
            minExpectedAmount: _minMintAmount
        });
        mintRequestsCounter = id + 1;
        emit MintRequestCreated(id, msg.sender, _depositAmount, _minMintAmount);
    }

    function cancelMint(uint256 _id) external mintRequestExist(_id) {
        Request storage r = mintRequests[_id];
        require(r.provider == msg.sender, IllegalCaller(r.provider, msg.sender));
        require(r.state == State.CREATED, IllegalState(State.CREATED, r.state));

        r.state = State.CANCELLED;
        IERC20(depositToken).safeTransfer(r.provider, r.amount);
        emit MintRequestCancelled(_id);
    }

    function completeMint(bytes32 _idempotencyKey, uint256 _id, uint256 _sharesToMint)
        external
        onlyRole(MINT_COMPLETER_ROLE)
        whenNotPaused
        mintRequestExist(_id)
    {
        Request storage r = mintRequests[_id];
        require(r.state == State.CREATED, IllegalState(State.CREATED, r.state));
        require(_sharesToMint != 0, ZeroAmount());

        uint256 amount = r.amount;
        address provider = r.provider;

        require(providersWhitelist.isAllowedAccount(provider), UnknownProvider(provider));
        require(_sharesToMint >= r.minExpectedAmount, InsufficientMintAmount(_sharesToMint, r.minExpectedAmount));

        require(!oracle.isStale(), OracleStale());
        uint256 price = oracle.getPrice();
        require(price != 0, InvalidPrice());
        uint256 actualShares = _shareScaleMultiplies ? (amount * _shareScale) / price : amount / (_shareScale * price);
        _assertWithinDeviation(_sharesToMint, actualShares);

        r.state = State.COMPLETED;

        IERC20(depositToken).safeTransfer(treasury, amount);
        IPermissionedToken(issueToken).mint(_idempotencyKey, provider, _sharesToMint);

        emit MintRequestCompleted(_idempotencyKey, _id, _sharesToMint);
    }

    function requestBurn(uint256 _sharesAmount, uint256 _minWithdrawalAmount)
        external
        onlyAllowedProvider
        whenNotPaused
        returns (uint256 id)
    {
        require(_sharesAmount != 0, ZeroAmount());
        uint256 floor = minBurnRequestAmount;
        require(_sharesAmount >= floor, BelowMinRequest(_sharesAmount, floor));

        IERC20(issueToken).safeTransferFrom(msg.sender, address(this), _sharesAmount);

        id = burnRequestsCounter;
        burnRequests[id] = Request({
            id: id,
            provider: msg.sender,
            state: State.CREATED,
            amount: _sharesAmount,
            minExpectedAmount: _minWithdrawalAmount
        });
        burnRequestsCounter = id + 1;
        emit BurnRequestCreated(id, msg.sender, _sharesAmount, _minWithdrawalAmount);
    }

    function cancelBurn(uint256 _id) external burnRequestExist(_id) {
        Request storage r = burnRequests[_id];
        require(r.provider == msg.sender, IllegalCaller(r.provider, msg.sender));
        require(r.state == State.CREATED, IllegalState(State.CREATED, r.state));

        r.state = State.CANCELLED;
        IERC20(issueToken).safeTransfer(r.provider, r.amount);
        emit BurnRequestCancelled(_id);
    }

    function completeBurn(bytes32 _idempotencyKey, uint256 _id, uint256 _depositToReturn)
        external
        onlyRole(BURN_COMPLETER_ROLE)
        whenNotPaused
        burnRequestExist(_id)
    {
        Request storage r = burnRequests[_id];
        require(r.state == State.CREATED, IllegalState(State.CREATED, r.state));
        require(_depositToReturn != 0, ZeroAmount());

        uint256 amount = r.amount;
        address provider = r.provider;

        require(providersWhitelist.isAllowedAccount(provider), UnknownProvider(provider));
        require(
            _depositToReturn >= r.minExpectedAmount, InsufficientWithdrawalAmount(_depositToReturn, r.minExpectedAmount)
        );

        require(!oracle.isStale(), OracleStale());
        uint256 price = oracle.getPrice();
        require(price != 0, InvalidPrice());
        uint256 actualDeposit = _shareScaleMultiplies ? (amount * price) / _shareScale : amount * price * _shareScale;
        _assertWithinDeviation(_depositToReturn, actualDeposit);

        r.state = State.COMPLETED;

        IPermissionedToken(issueToken).burn(_idempotencyKey, address(this), amount);
        // slither-disable-next-line arbitrary-send-erc20
        IERC20(depositToken).safeTransferFrom(treasury, provider, _depositToReturn);

        emit BurnRequestCompleted(_idempotencyKey, _id, _depositToReturn);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(UNPAUSER_ROLE) {
        _unpause();
    }

    function setTreasury(address _newTreasury) external onlyRole(TREASURY_CONFIG_ROLE) {
        _setTreasury(_newTreasury);
    }

    function setProvidersWhitelist(address _newWhitelist) external onlyRole(WHITELIST_CONFIG_ROLE) {
        _setProvidersWhitelist(_newWhitelist);
    }

    function setOracle(address _newOracle) external onlyRole(ORACLE_CONFIG_ROLE) {
        uint256 oldPrice = oracle.getPrice();
        _setOracle(_newOracle);
        require(oracle.baseAsset() == issueToken, OracleAssetMismatch(oracle.baseAsset(), issueToken));
        require(oracle.quoteAsset() == depositToken, OracleAssetMismatch(oracle.quoteAsset(), depositToken));

        uint8 issueDecimals = IERC20Metadata(issueToken).decimals();
        uint8 depositDecimals = IERC20Metadata(depositToken).decimals();
        uint8 priceDecimals = oracle.priceDecimals();
        uint256 sumIssuePrice = uint256(issueDecimals) + uint256(priceDecimals);
        bool multiplies = sumIssuePrice >= depositDecimals;
        uint256 newScale =
            multiplies ? 10 ** (sumIssuePrice - depositDecimals) : 10 ** (depositDecimals - sumIssuePrice);
        require(multiplies == _shareScaleMultiplies && newScale == _shareScale, ShareScaleMismatch());

        require(!oracle.isStale(), OracleStale());
        uint256 newPrice = oracle.getPrice();
        require(newPrice != 0, InvalidPrice());
        _assertWithinDeviation(newPrice, oldPrice);

        _assertMintGuardOracleConsistent();
    }

    function setMinMintRequestAmount(uint256 _amount) external onlyRole(ISSUANCE_CONFIG_ROLE) {
        minMintRequestAmount = _amount;
        emit MinMintRequestAmountSet(_amount);
    }

    function setMinBurnRequestAmount(uint256 _amount) external onlyRole(ISSUANCE_CONFIG_ROLE) {
        minBurnRequestAmount = _amount;
        emit MinBurnRequestAmountSet(_amount);
    }

    function setPriceDeviationBps(uint256 _bps) external onlyRole(ISSUANCE_CONFIG_ROLE) {
        _setPriceDeviationBps(_bps);
    }

    function emergencyWithdraw(address _token, address _recipient) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_recipient != address(0), ZeroAddress());
        uint256 balance = IERC20(_token).balanceOf(address(this));
        if (balance > 0) {
            IERC20(_token).safeTransfer(_recipient, balance);
        }
        emit EmergencyWithdrawn(_token, balance);
    }

    function getMintRequest(uint256 _id) external view returns (Request memory) {
        return mintRequests[_id];
    }

    function getBurnRequest(uint256 _id) external view returns (Request memory) {
        return burnRequests[_id];
    }

    function _assertMintGuardOracleConsistent() internal view {
        IMintGuard mintGuard = IPermissionedToken(issueToken).mintGuard();
        require(address(mintGuard) != address(0), MintGuardNotSetOnToken(issueToken));
        address mintGuardOracle = mintGuard.oracle();
        require(mintGuardOracle == address(oracle), MintGuardOracleMismatch(mintGuardOracle, address(oracle)));
    }

    function _assertWithinDeviation(uint256 _claimed, uint256 _actual) internal view {
        require(_actual != 0, InvalidPrice());
        uint256 bps = priceDeviationBps;
        uint256 maxDelta = (_actual * bps) / _BPS_DENOMINATOR;
        uint256 delta = _claimed >= _actual ? _claimed - _actual : _actual - _claimed;
        require(delta <= maxDelta, PriceDeviationExceeded(_claimed, _actual, bps));
    }

    function _setTreasury(address _newTreasury) internal {
        require(_newTreasury != address(0), ZeroAddress());
        treasury = _newTreasury;
        emit TreasurySet(_newTreasury);
    }

    function _setProvidersWhitelist(address _newWhitelist) internal {
        require(_newWhitelist != address(0), ZeroAddress());
        require(_newWhitelist.code.length != 0, NotAContract(_newWhitelist));
        providersWhitelist = IAddressesWhitelist(_newWhitelist);
        emit ProvidersWhitelistSet(_newWhitelist);
    }

    function _setOracle(address _newOracle) internal {
        require(_newOracle != address(0), ZeroAddress());
        require(_newOracle.code.length != 0, NotAContract(_newOracle));
        oracle = IOracle(_newOracle);
        emit OracleSet(_newOracle);
    }

    function _setPriceDeviationBps(uint256 _bps) internal {
        require(_bps != 0 && _bps <= _BPS_DENOMINATOR, InvalidPriceDeviationBps(_bps));
        priceDeviationBps = _bps;
        emit PriceDeviationBpsSet(_bps);
    }
}

