// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import {IOracle} from "./IOracle.sol";
import {IAddressesWhitelist} from "./IAddressesWhitelist.sol";

interface IExternalRequestsManager {
    enum State {
        NULL,
        CREATED,
        COMPLETED,
        CANCELLED
    }

    struct Request {
        uint256 id;
        address provider;
        State state;
        uint256 amount;
        uint256 minExpectedAmount;
    }

    struct InitParams {
        address admin;
        address treasury;
        address providersWhitelist;
        address oracle;
        uint256 priceDeviationBps;
    }

    event TreasurySet(address indexed _treasury);
    event ProvidersWhitelistSet(address indexed _whitelist);
    event OracleSet(address indexed _oracle);
    event MinMintRequestAmountSet(uint256 _amount);
    event MinBurnRequestAmountSet(uint256 _amount);
    event PriceDeviationBpsSet(uint256 _bps);

    event MintRequestCreated(
        uint256 indexed _id, address indexed _provider, uint256 _depositAmount, uint256 _minMintAmount
    );
    event MintRequestCancelled(uint256 indexed _id);
    event MintRequestCompleted(bytes32 indexed _idempotencyKey, uint256 indexed _id, uint256 _mintedAmount);

    event BurnRequestCreated(
        uint256 indexed _id, address indexed _provider, uint256 _sharesAmount, uint256 _minWithdrawalAmount
    );
    event BurnRequestCancelled(uint256 indexed _id);
    event BurnRequestCompleted(bytes32 indexed _idempotencyKey, uint256 indexed _id, uint256 _withdrawalAmount);

    event EmergencyWithdrawn(address indexed _token, uint256 _amount);

    error ZeroAddress();
    error ZeroAmount();
    error NotAContract(address _account);
    error InvalidPriceDeviationBps(uint256 _bps);
    error OracleAssetMismatch(address _oracleAsset, address _ermAsset);
    error MintGuardNotSetOnToken(address _token);
    error MintGuardOracleMismatch(address _mintGuardOracle, address _ermOracle);
    error ShareScaleMismatch();
    error UnknownProvider(address _account);
    error RequestNotExist(uint256 _id);
    error IllegalState(State _expected, State _actual);
    error IllegalCaller(address _expected, address _actual);
    error PriceDeviationExceeded(uint256 _claimed, uint256 _actual, uint256 _allowedBps);
    error InsufficientMintAmount(uint256 _actual, uint256 _minExpected);
    error InsufficientWithdrawalAmount(uint256 _actual, uint256 _minExpected);
    error InvalidPrice();
    error OracleStale();
    error BelowMinRequest(uint256 _amount, uint256 _minimum);

    function requestMint(uint256 _depositAmount, uint256 _minMintAmount) external returns (uint256 id);
    function cancelMint(uint256 _id) external;
    function completeMint(bytes32 _idempotencyKey, uint256 _id, uint256 _sharesToMint) external;

    function requestBurn(uint256 _sharesAmount, uint256 _minWithdrawalAmount) external returns (uint256 id);
    function cancelBurn(uint256 _id) external;
    function completeBurn(bytes32 _idempotencyKey, uint256 _id, uint256 _depositToReturn) external;

    function pause() external;
    function unpause() external;

    function setTreasury(address _newTreasury) external;
    function setProvidersWhitelist(address _newWhitelist) external;
    function setOracle(address _newOracle) external;
    function setMinMintRequestAmount(uint256 _amount) external;
    function setMinBurnRequestAmount(uint256 _amount) external;
    function setPriceDeviationBps(uint256 _bps) external;

    function emergencyWithdraw(address _token, address _recipient) external;

    function issueToken() external view returns (address);
    function depositToken() external view returns (address);
    function treasury() external view returns (address);
    function oracle() external view returns (IOracle);
    function providersWhitelist() external view returns (IAddressesWhitelist);
    function minMintRequestAmount() external view returns (uint256);
    function minBurnRequestAmount() external view returns (uint256);
    function priceDeviationBps() external view returns (uint256);
    function getMintRequest(uint256 _id) external view returns (Request memory);
    function getBurnRequest(uint256 _id) external view returns (Request memory);
}

