// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import {IAddressesWhitelist} from "./IAddressesWhitelist.sol";
import {IMintGuard} from "./IMintGuard.sol";

interface IPermissionedToken {
    event WhitelistSet(address indexed _whitelist);
    event MintGuardSet(address indexed _mintGuard);

    error IdempotencyKeyAlreadyExist(bytes32 _idempotencyKey);
    error ZeroAddress();
    error ZeroAmount();
    error NotAContract(address _account);
    error NotWhitelisted(address _account);
    error MintGuardNotBound(address _mintGuard);
    error MintGuardNotSet();

    function mint(bytes32 _idempotencyKey, address _to, uint256 _amount) external;
    function burn(bytes32 _idempotencyKey, address _from, uint256 _amount) external;

    function pause() external;
    function unpause() external;

    function setWhitelist(address _newWhitelist) external;
    function setMintGuard(address _newMintGuard) external;

    function whitelist() external view returns (IAddressesWhitelist);
    function mintGuard() external view returns (IMintGuard);
}

