// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

interface IMintGuard {
    struct InitParams {
        address admin;
        address token;
        address oracle;
        uint256 mintLimitPerWindowBps;
        uint256 mintLimitFloor;
        uint256 windowDuration;
        uint256 maxTotalSupply;
        uint256 oracleRotationDeviationBps;
    }

    event OracleSet(address indexed _oracle);
    event MintLimitPerWindowBpsSet(uint256 _bps);
    event MintLimitFloorSet(uint256 _floor);
    event MaxTotalSupplySet(uint256 _cap);
    event OracleRotationDeviationBpsSet(uint256 _bps);

    error ZeroAddress();
    error NotAContract(address _account);
    error NotToken(address _caller);
    error OracleStale();
    error InvalidPrice();
    error InvalidWindowDuration();
    error InvalidMintLimitPerWindowBps(uint256 _bps);
    error MintRateLimitExceeded(uint256 _attempted, uint256 _limit);
    error SupplyCapExceeded(uint256 _currentSupply, uint256 _amount, uint256 _cap);
    error OracleAssetMismatch(address _oracleBaseAsset, address _token);
    error InvalidOracleRotationDeviationBps(uint256 _bps);
    error OracleRotationDeviationExceeded(uint256 _newPrice, uint256 _oldPrice, uint256 _allowedBps);

    function preMint(uint256 _amount, uint256 _currentSupply) external;

    function setOracle(address _newOracle) external;
    function setMintLimitPerWindowBps(uint256 _bps) external;
    function setMintLimitFloor(uint256 _floor) external;
    function setMaxTotalSupply(uint256 _cap) external;
    function setOracleRotationDeviationBps(uint256 _bps) external;

    function token() external view returns (address);
    function oracle() external view returns (address);
    function windowDuration() external view returns (uint256);
    function mintLimitPerWindowBps() external view returns (uint256);
    function mintLimitFloor() external view returns (uint256);
    function maxTotalSupply() external view returns (uint256);
    function oracleRotationDeviationBps() external view returns (uint256);
    function currentBucket() external view returns (uint256);
    function mintedInCurrentBucket() external view returns (uint256);
    function availableMintInWindow(uint256 _currentSupply) external view returns (uint256);
}

